/**
 * Fast report pipeline + MetricKnowledge store.
 *
 * Everything external is mocked (Mongo model methods, axios -> Anthropic,
 * UsageLog), so these run offline. They pin the three promises of the change:
 *   1. the assembled analysis has exactly the legacy shape (all 9 metric fields)
 *   2. a marker is generated by AI once, then served from cache (and concurrent
 *      reports share a single generation)
 *   3. failures degrade safely (NOT_MEDICAL stays a rejection, malformed output
 *      falls back to the legacy path, a failed generation is never persisted)
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const { mock } = require('node:test');
const axios = require('axios');
const { Readable } = require('stream');

const MetricKnowledge = require('../models/MetricKnowledge');
const UsageLog = require('../models/UsageLog');
const cache = require('../utils/cache');
const knowledge = require('../services/metricKnowledgeService');
const aiService = require('../services/aiService');

const METRIC_FIELDS = ['value', 'unit', 'status', 'normalRange', 'whatIsThis', 'whatItDoes', 'lowHighImpact', 'topFoods', 'symptoms'];
const TOP_LEVEL_KEYS = [
  'patientName', 'reportDate', 'documentCategory', 'documentType', 'healthScore',
  'summary', 'doctorSummary', 'doctorAdvice', 'summaryPoints', 'keyFindings',
  'metrics', 'deficiencies', 'recommendations', 'doctorConsultation',
];

const goodEntry = (label) => ({
  whatIsThis: `${label} is a marker.`,
  whatItDoes: `${label} does things in the body.`,
  lowHighImpact: `Low or high ${label} matters.`,
  topFoods: ['A', 'B', 'C'],
  symptoms: ['X', 'Y'],
});

async function freshStore(t, { stored = [] } = {}) {
  knowledge._resetL1();
  t.mock.method(MetricKnowledge, 'find', () => ({ lean: async () => stored }));
  const writes = [];
  t.mock.method(MetricKnowledge, 'bulkWrite', async (ops) => { writes.push(...ops); return {}; });
  t.mock.method(UsageLog, 'create', async () => ({}));
  return writes;
}

// ---------------------------------------------------------------------------
// MetricKnowledge store
// ---------------------------------------------------------------------------

test('knowledgeKey: aliases of one marker share a key; junk is rejected', () => {
  const k = knowledge.knowledgeKey;
  assert.equal(k('Hb'), k('Haemoglobin'));
  assert.equal(k('HGB'), 'hemoglobin');
  assert.equal(k('T S H'), 'tsh');
  assert.equal(k(''), '');
  assert.equal(k('x'.repeat(200)), '');
});

test('sanitizeEntry: requires the three prose fields, trims lists', () => {
  assert.equal(knowledge.sanitizeEntry({ whatIsThis: 'a', whatItDoes: 'b' }), null);
  assert.equal(knowledge.sanitizeEntry(null), null);
  const ok = knowledge.sanitizeEntry({
    whatIsThis: ' a ', whatItDoes: 'b', lowHighImpact: 'c',
    topFoods: ['1', '2', '3', '4', '5', '6', '7'], symptoms: 'not-an-array',
  });
  assert.equal(ok.whatIsThis, 'a');
  assert.equal(ok.topFoods.length, 5);
  assert.deepEqual(ok.symptoms, []);
});

test('mergeKnowledgeIntoMetrics: always emits all 9 fields, knowledge wins, gaps become empty', () => {
  const map = new Map([['hemoglobin', goodEntry('Hemoglobin')]]);
  const merged = knowledge.mergeKnowledgeIntoMetrics(
    {
      Hb: { value: 12, unit: 'g/dL', status: 'low', normalRange: '13-17', whatItDoes: 'model text' },
      'Mystery Marker': { value: 3, unit: 'u', status: 'normal', normalRange: '1-5' },
    },
    map
  );
  assert.deepEqual(Object.keys(merged.Hb), METRIC_FIELDS);
  assert.equal(merged.Hb.whatItDoes, 'Hemoglobin does things in the body.');
  const mystery = merged['Mystery Marker'];
  assert.deepEqual(Object.keys(mystery).sort(), [...METRIC_FIELDS].sort());
  assert.equal(mystery.whatItDoes, '');
  assert.deepEqual(mystery.topFoods, []);
});

test('resolve: first sight generates + persists once, then is served from cache with no AI call', async (t) => {
  const writes = await freshStore(t);
  const gen = t.mock.method(knowledge._deps, 'generateText', async (names) => ({
    model: 'test-model',
    text: JSON.stringify({ metrics: Object.fromEntries(names.map(n => [n, goodEntry(n)])) }),
  }));
  const name = `Testmarker-${Date.now()}-a`;

  const first = await knowledge.resolveMetricKnowledge([name]);
  assert.equal(first.missing.length, 0);
  assert.equal(gen.mock.callCount(), 1);
  assert.equal(writes.length, 1);
  assert.equal(writes[0].updateOne.upsert, true);
  assert.ok(writes[0].updateOne.update.$setOnInsert.whatItDoes);

  const second = await knowledge.resolveMetricKnowledge([name]);
  assert.equal(second.missing.length, 0);
  assert.equal(gen.mock.callCount(), 1, 'second lookup must not call the AI');
  await cache.delete(`metricKnowledge:v1:${knowledge.knowledgeKey(name)}`);
});

test('resolve: concurrent reports needing the same new marker share ONE generation', async (t) => {
  await freshStore(t);
  const gen = t.mock.method(knowledge._deps, 'generateText', async (names) => {
    await new Promise(r => setTimeout(r, 30));
    return { model: 'm', text: JSON.stringify({ metrics: Object.fromEntries(names.map(n => [n, goodEntry(n)])) }) };
  });
  const name = `Testmarker-${Date.now()}-b`;

  const [a, b] = await Promise.all([
    knowledge.resolveMetricKnowledge([name]),
    knowledge.resolveMetricKnowledge([name]),
  ]);
  assert.equal(a.missing.length + b.missing.length, 0);
  assert.equal(gen.mock.callCount(), 1);
  await cache.delete(`metricKnowledge:v1:${knowledge.knowledgeKey(name)}`);
});

test('resolve: a failed generation is reported missing and never persisted or cached', async (t) => {
  const writes = await freshStore(t);
  const gen = t.mock.method(knowledge._deps, 'generateText', async () => { throw new Error('529 overloaded'); });
  const name = `Testmarker-${Date.now()}-c`;

  const res = await knowledge.resolveMetricKnowledge([name]);
  assert.equal(res.missing.length, 1);
  assert.equal(writes.length, 0);
  assert.equal(gen.mock.callCount(), 2, 'one retry, then give up');

  // A later attempt must try again rather than see a poisoned "empty" cache entry.
  gen.mock.restore();
  t.mock.method(knowledge._deps, 'generateText', async (names) => ({
    model: 'm', text: JSON.stringify({ metrics: Object.fromEntries(names.map(n => [n, goodEntry(n)])) }),
  }));
  const retry = await knowledge.resolveMetricKnowledge([name]);
  assert.equal(retry.missing.length, 0);
  await cache.delete(`metricKnowledge:v1:${knowledge.knowledgeKey(name)}`);
});

test('resolve: a row already in Mongo is used without any AI call', async (t) => {
  const key = knowledge.knowledgeKey('Ferritin');
  await freshStore(t, { stored: [{ key, ...goodEntry('Ferritin') }] });
  await cache.delete(`metricKnowledge:v1:${key}`);
  const gen = t.mock.method(knowledge._deps, 'generateText', async () => { throw new Error('should not be called'); });

  const res = await knowledge.resolveMetricKnowledge(['Ferritin']);
  assert.equal(res.missing.length, 0);
  assert.equal(gen.mock.callCount(), 0);
  assert.equal(res.map.get(key).whatIsThis, 'Ferritin is a marker.');
  await cache.delete(`metricKnowledge:v1:${key}`);
});

// ---------------------------------------------------------------------------
// Pipeline (axios -> Anthropic mocked)
// ---------------------------------------------------------------------------

const anthropicReply = (obj, streamed = false) => {
  const text = typeof obj === 'string' ? obj : JSON.stringify(obj);
  if (!streamed) {
    return { data: { content: [{ text }], usage: { input_tokens: 10, output_tokens: 10 }, stop_reason: 'end_turn' } };
  }
  // The legacy path requests 32K tokens, which the service streams (SSE).
  const sse = (evt) => `data: ${JSON.stringify(evt)}

`;
  return {
    data: Readable.from([
      sse({ type: 'message_start', message: { usage: { input_tokens: 10 } } }),
      sse({ type: 'content_block_delta', delta: { type: 'text_delta', text } }),
      sse({ type: 'message_delta', usage: { output_tokens: 10 }, delta: { stop_reason: 'end_turn' } }),
    ]),
  };
};

const CORE_JSON = {
  patientName: 'Asha', reportDate: '2026-01-05', documentCategory: 'lab_report', documentType: 'Blood Test', healthScore: 71,
  metrics: { Hemoglobin: { value: 12.1, unit: 'g/dL', status: 'low', normalRange: '13-17' } },
};
const NARRATIVE_PARTS = {
  A: ['doctorSummary'],
  B: ['summary', 'doctorAdvice', 'summaryPoints', 'keyFindings'],
  C: ['deficiencies', 'recommendations', 'doctorConsultation'],
};
const NARRATIVE_JSON = {
  summary: '• one', doctorSummary: 'Hello Asha.', doctorAdvice: ['a'], summaryPoints: ['p'], keyFindings: ['k'],
  deficiencies: [{ name: 'Iron', severity: 'mild', currentValue: '1', normalRange: '2', explanation: 'e' }],
  recommendations: { immediate: [], lifestyle: [] }, doctorConsultation: { recommended: false, urgency: 'low', specializations: [] },
};

function mockAnthropic(t, { core = CORE_JSON, narrative = NARRATIVE_JSON, legacy = null } = {}) {
  return t.mock.method(axios, 'post', async (url, body) => {
    const system = body.system?.[0]?.text || '';
    if (system.startsWith('Extract the structured data')) return anthropicReply(core);
    if (system.startsWith('Analyze this health report as an expert medical AI and write')) {
      if (narrative.isMedical === false) return anthropicReply(narrative);
      const part = /PART ([ABC]):/.exec(system)[1];
      return anthropicReply(Object.fromEntries(NARRATIVE_PARTS[part].map(k => [k, narrative[k]])));
    }
    if (system.startsWith('You write reference notes')) {
      return anthropicReply({ metrics: { Hemoglobin: goodEntry('Hemoglobin') } });
    }
    if (system.startsWith('Analyze this health report as an expert medical AI. You MUST') && legacy) return anthropicReply(legacy, body.stream === true);
    throw new Error(`unexpected prompt: ${system.slice(0, 60)}`);
  });
}

const callAnalyze = () => aiService.analyzeHealthReport('Hemoglobin 12.1 g/dL', { name: 'Asha' }, null, 'general', { userId: null });

test('pipeline: flag off -> legacy path only (single combined call)', async (t) => {
  await freshStore(t);
  delete process.env.FAST_REPORT_PIPELINE;
  const legacy = { ...CORE_JSON, ...NARRATIVE_JSON };
  const post = mockAnthropic(t, { legacy });
  const out = await callAnalyze();
  assert.equal(post.mock.callCount(), 1);
  assert.equal(out.patientName, 'Asha');
});

test('pipeline: flag on -> same shape as legacy, all 9 metric fields filled, no legacy call', async (t) => {
  await freshStore(t);
  process.env.FAST_REPORT_PIPELINE = 'true';
  t.after(() => { delete process.env.FAST_REPORT_PIPELINE; });
  await cache.delete(`metricKnowledge:v1:hemoglobin`);
  const post = mockAnthropic(t);

  const out = await callAnalyze();
  assert.deepEqual(Object.keys(out), TOP_LEVEL_KEYS);
  assert.deepEqual(Object.keys(out.metrics.Hemoglobin), METRIC_FIELDS);
  assert.equal(out.metrics.Hemoglobin.value, 12.1);
  assert.equal(out.metrics.Hemoglobin.whatItDoes, 'Hemoglobin does things in the body.');
  assert.equal(out.healthScore, 71);
  assert.equal(out.doctorSummary, 'Hello Asha.');
  assert.deepEqual(out.doctorAdvice, ['a']);
  assert.equal(out.deficiencies[0].name, 'Iron');
  assert.equal(out.doctorConsultation.urgency, 'low');
  assert.equal(post.mock.calls.filter(c => c.arguments[1].system[0].text.startsWith('Analyze this health report as an expert medical AI and write')).length, 3, 'narrative runs as 3 parallel parts');
  const prompts = post.mock.calls.map(c => c.arguments[1].system[0].text.slice(0, 20));
  assert.ok(!prompts.some(p => p.startsWith('Analyze this health report as an expert medical AI. You MUST')));
  await cache.delete(`metricKnowledge:v1:hemoglobin`);
});

test('pipeline: NOT_MEDICAL is only raised after a confirming second pass, and wins over narrative', async (t) => {
  await freshStore(t);
  process.env.FAST_REPORT_PIPELINE = 'true';
  t.after(() => { delete process.env.FAST_REPORT_PIPELINE; });
  const post = mockAnthropic(t, { core: { isMedical: false, message: 'Not medical.' } });

  await assert.rejects(callAnalyze(), (err) => err.code === 'NOT_MEDICAL');
  const corePrompts = post.mock.calls.filter(c => c.arguments[1].system[0].text.startsWith('Extract the structured data'));
  assert.equal(corePrompts.length, 2, 'rejection must be confirmed by a second core pass');
  assert.ok(!post.mock.calls.some(c => c.arguments[1].system[0].text.startsWith('Analyze this health report as an expert medical AI. You MUST')), 'no legacy retry for a genuine rejection');
});

test('pipeline: a one-off spurious "not medical" verdict does not reject a valid report', async (t) => {
  await freshStore(t);
  process.env.FAST_REPORT_PIPELINE = 'true';
  t.after(() => { delete process.env.FAST_REPORT_PIPELINE; });
  await cache.delete('metricKnowledge:v1:hemoglobin');
  let coreCalls = 0;
  t.mock.method(axios, 'post', async (url, body) => {
    const system = body.system?.[0]?.text || '';
    if (system.startsWith('Extract the structured data')) {
      coreCalls++;
      return anthropicReply(coreCalls === 1 ? { isMedical: false, message: 'Not medical.' } : CORE_JSON);
    }
    if (system.startsWith('Analyze this health report as an expert medical AI and write')) {
      const part = /PART ([ABC]):/.exec(system)[1];
      return anthropicReply(Object.fromEntries(NARRATIVE_PARTS[part].map(k => [k, NARRATIVE_JSON[k]])));
    }
    return anthropicReply({ metrics: { Hemoglobin: goodEntry('Hemoglobin') } });
  });

  const out = await callAnalyze();
  assert.equal(coreCalls, 2);
  assert.equal(out.patientName, 'Asha');
  await cache.delete('metricKnowledge:v1:hemoglobin');
});

test('pipeline: narrative prompts carry no medical gate (only core decides)', () => {
  const src = require('fs').readFileSync(require.resolve('../services/aiService'), 'utf8');
  const parts = src.match(/const REPORT_NARRATIVE_\w+_PROMPT = `[\s\S]*?`;/g) || [];
  assert.equal(parts.length, 3);
  for (const part of parts) assert.ok(!part.includes('${GATE_STEP}'));
});

test('pipeline: malformed core output falls back to the legacy path', async (t) => {
  await freshStore(t);
  process.env.FAST_REPORT_PIPELINE = 'true';
  t.after(() => { delete process.env.FAST_REPORT_PIPELINE; });
  const legacy = { ...CORE_JSON, ...NARRATIVE_JSON };
  mockAnthropic(t, { core: 'sorry, I cannot do that', legacy });

  const out = await callAnalyze();
  assert.equal(out.patientName, 'Asha');
  assert.equal(out.doctorSummary, 'Hello Asha.');
});

test('pipeline: unresolved knowledge still yields the full shape (empty strings), report not failed', async (t) => {
  await freshStore(t);
  process.env.FAST_REPORT_PIPELINE = 'true';
  t.after(() => { delete process.env.FAST_REPORT_PIPELINE; });
  await cache.delete(`metricKnowledge:v1:hemoglobin`);
  t.mock.method(axios, 'post', async (url, body) => {
    const system = body.system?.[0]?.text || '';
    if (system.startsWith('Extract the structured data')) return anthropicReply(CORE_JSON);
    if (system.startsWith('Analyze this health report as an expert medical AI and write')) {
      const part = /PART ([ABC]):/.exec(system)[1];
      return anthropicReply(Object.fromEntries(NARRATIVE_PARTS[part].map(k => [k, NARRATIVE_JSON[k]])));
    }
    throw new Error('knowledge model down');
  });

  const out = await callAnalyze(); // no reportId in context -> no backfill timer
  assert.deepEqual(Object.keys(out.metrics.Hemoglobin), METRIC_FIELDS);
  assert.equal(out.metrics.Hemoglobin.whatItDoes, '');
  assert.deepEqual(out.metrics.Hemoglobin.topFoods, []);
});
